function canReachLastStone(stones: number[]): boolean {
  const at = new Map<number, number>();
  stones.forEach((p, i) => at.set(p, i));
  const last = stones.length - 1;
  const seen = new Set<number>();
  const go = (i: number, k: number): boolean => {
    if (i === last) return true;
    const key = i * 4096 + k; // k never exceeds n, which is below 4096
    if (seen.has(key)) return false;
    seen.add(key);
    for (const step of [k + 1, k, k - 1]) {
      if (step <= 0) continue;
      const j = at.get(stones[i] + step);
      if (j !== undefined && go(j, step)) return true;
    }
    return false;
  };
  return go(0, 0);
}

