function canReachLastStone(stones: number[]): boolean {
  const speeds = new Map<number, Set<number>>();
  for (const p of stones) speeds.set(p, new Set());
  speeds.get(0)!.add(0);
  for (const p of stones) {
    for (const k of speeds.get(p)!) {
      for (let step = k - 1; step <= k + 1; step++) {
        if (step <= 0) continue;
        const target = speeds.get(p + step);
        if (target) target.add(step);
      }
    }
  }
  return speeds.get(stones[stones.length - 1])!.size > 0;
}

